head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > checkAll]<br/>Body Column 의 ID 또는 인덱스값을 사용하여 전체 Body Cell 을 일괄 체크하거나 해제합니다.",
    "validation" : [
        "Body Column 의 inputType='checkbox','custom' 인 경우에만 동작합니다.",
        "columnInfo(필수) 파라미터로 일괄 체크/해제하려는 Body Column 의 ID 또는 인덱스값을 설정해야 합니다. (인덱스는 0 부터 시작)",
        "Body Column 의 inputType 이 'checkbox','custom' 인 경우에만 동작해야 합니다.",
        "data(선택) 파라미터가 1/true/trueValue 와 일치하면 모든 Cell 을 체크 상태로 설정해야 합니다.",
        "data(선택) 파라미터가 0/false/falseValue 와 일치하면 모든 Cell 을 체크 해제 상태로 설정해야 합니다.",
        "data(선택) 파라미터가 undefined 또는 위 두 조건에 해당하지 않으면 각 Cell 의 현재 체크 상태를 토글해야 합니다.",
        "inputType='custom' 인 경우 실제 Cell 의 inputType 이 'checkbox' 인 Cell 만 처리해야 합니다.",
        "readOnly/disabled 상태와 관계없이 모든 Cell 에 데이터를 설정해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target/dataList 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 컬럼 inputType 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="0:name(text) / 1:chk(checkbox) / 2:cst(custom, Row0·Row2=checkbox · Row1·Row3=text) / 3:memo(text)"', '', 'label1');

    // GridView 와 바인딩할 DataList 동적 생성
    // - chk : checkbox 컬럼 원본값(1/0)
    // - cst : custom 컬럼 원본값(checkbox 셀은 1/0, text 셀은 표시 문자열)
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="chk" name="chk" dataType="text"></w2:column>';
    strDlt += '<w2:column id="cst" name="cst" dataType="text"></w2:column>';
    strDlt += '<w2:column id="memo" name="memo" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    // 초기값: chk / cst 모두 "0"(미체크). cst 의 Row1,Row3(text 셀) 도 "0" 으로 두어 checkbox 셀만 변경됨을 명확히 비교
    let jsonData = [
        { "name": "John", "chk": "0", "cst": "0", "memo": "row0" },
        { "name": "Jane", "chk": "0", "cst": "0", "memo": "row1" },
        { "name": "Mike", "chk": "0", "cst": "0", "memo": "row2" },
        { "name": "Amy",  "chk": "0", "cst": "0", "memo": "row3" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // Property 설정은 createCList 공통 함수 사용
    // setCellInputTypeCustom=true → custom 컬럼에 setCellInputType 으로 행별 inputType 부여
    let properties = {
        dataList: "data:dlt_bind",
        setCellInputTypeCustom: "true",
        checkAllType: "false",
    };
    let cList = $c.gcm.createCList(properties);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();
    let strTarget = '';

    // target 생성 (Header 4컬럼: name / chk(checkbox) / cst(custom) / memo)
    // 마지막 memo 컬럼 width="*" 로 가로 스크롤 방지
    strTarget += '<w2:gridView ' + strNameSpace + ' ' + cList + ' id="" style="width:600px;height:230px;">';
    strTarget += '<w2:caption style="" id="caption1" value="checkAll 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="130" style="" inputType="text" id="hcol1" value="이름"></w2:column>';
    strTarget += '<w2:column width="130" style="" inputType="checkbox" id="hcol2" value="체크(checkbox)"></w2:column>';
    strTarget += '<w2:column width="180" style="" inputType="checkbox" id="hcol3" value="혼합(custom)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="메모"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    // index 0 : name (text)
    strTarget += '<w2:column width="130" style="" inputType="text" id="name" dataList="name"></w2:column>';
    // index 1 : chk (checkbox) - trueValue="1" falseValue="0"
    strTarget += '<w2:column width="130" style="" inputType="checkbox" id="chk" dataList="chk" trueValue="1" falseValue="0"></w2:column>';
    // index 2 : cst (custom) - 행별 inputType 혼합 (setCellInputType 으로 지정), checkbox 셀은 trueValue/falseValue 상속
    strTarget += '<w2:column width="180" style="" inputType="custom" id="cst" dataList="cst" trueValue="1" falseValue="0"></w2:column>';
    // index 3 : memo (text) - width="*"
    strTarget += '<w2:column width="*" style="" inputType="text" id="memo" dataList="memo"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // cst(custom) 컬럼 행별 inputType 부여 : Row0/Row2 = checkbox, Row1/Row3 = text
    //  → checkAll 시 checkbox 셀(Row0,Row2)만 처리되고 text 셀(Row1,Row3)은 영향 없음 (@spec1)
    target1.setCellInputType(0, "cst", { inputType: "checkbox", trueValue: "1", falseValue: "0" });
    target1.setCellInputType(1, "cst", { inputType: "text" });
    target1.setCellInputType(2, "cst", { inputType: "checkbox", trueValue: "1", falseValue: "0" });
    target1.setCellInputType(3, "cst", { inputType: "text" });

    // Row1 disabled, Row2 readOnly (chk Column 기준)
    //  → readOnly/disabled 상태와 무관하게 checkAll 이 데이터를 설정함을 검증 (@spec3)
    target1.setRowDisabled(1, true);
    target1.setRowReadOnly(2, true);
}



// 지정 컬럼의 전체 행 데이터를 "행:값" 형태로 수집 (체크 상태 확인용)
scwin.getColState = function (colId) {
    let len = target1.getRowCount();
    let arr = [];
    for (let i = 0; i < len; i++) {
        arr.push(i + "=" + target1.getCellData(i, colId));
    }
    return arr.join(", ");
}



// checkAll 확인 : par_columnInfo(컬럼 인덱스) + par_data 로 호출 후 해당 컬럼 전체 셀 데이터 출력
//  - data=true/1   : 전체 체크 (모두 1)
//  - data=false/0  : 전체 해제 (모두 0)
//  - data=undefined: 각 Cell 현재 상태 토글
scwin.btn_checkAll_onclick = function () {
    let colIndex = Number(par_columnInfo.getValue());
    let dataSel = par_data.getValue();

    // par_data 가 'undefined' 이면 인자 자체를 생략 (선택 파라미터 생략 동작 확인)
    let dataArg;
    if (dataSel === 'undefined' || dataSel === '') {
        target1.checkAll(colIndex);
        dataArg = '(생략)';
    } else if (dataSel === 'true' || dataSel === 'false') {
        target1.checkAll(colIndex, (dataSel === 'true'));
        dataArg = dataSel;
    } else {
        // '1' / '0' 은 문자열 그대로 전달 (trueValue/falseValue 일치 케이스)
        target1.checkAll(colIndex, dataSel);
        dataArg = "'" + dataSel + "'";
    }

    let colId = (colIndex === 1) ? "chk" : "cst";
    wf_body_bottom.getObj("scwin").setReturnValue("checkAll(" + colIndex + ", " + dataArg + ") → [" + colId + " 컬럼] " + scwin.getColState(colId));
}
